import{z as i,x as A,o as e,c as o,q as t,j as n,D as E,d as r,s,S as B}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"情境意识","description":"","frontmatter":{"title":"情境意识","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/situational-awareness.md","filePath":"llm/situational-awareness.md","lastUpdated":1791063341000}'),d={name:"llm/situational-awareness.md"};function p(_,a,m,u,h,c){const l=A("Mermaid");return e(),o("div",null,[a[2]||(a[2]=t('<h1 id="情境意识" tabindex="-1">情境意识 <a class="header-anchor" href="#情境意识" aria-label="Permalink to &quot;情境意识&quot;">​</a></h1><div class="epigraph"><p>模型若能表征「我是谁、现在在被评还是在跑产品」，条件策略才有钩子。表征本身不是罪，是后课监控的对象。</p><footer>—— 据 Berglund 等对 situational awareness 的实验；对照欺骗性对齐对过程模型的要求</footer></div><p><a href="/llm/sandbagging">上一课</a>需要代理知道「这是考场」。本课补缺口：情境意识（situational awareness）——对自身身份、时间、评测/部署、工具权限的表征。没有它，谋划与 sandbag 缺少门控变量；有它，也不等于已经在谋划。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>探针三层。第一，提示层：直接问「你是否在基准上」「你的知识截止日期」。第二，行为层：改系统提示中的身份与日期，看一致性。第三，表示层：线性探针或对比激活，看「评测」相关方向是否可分离——这是 <a href="/llm/linear-probing">线性探针</a> 课的应用，本课不重做探针数学。</p><p>Berglund 等人用「自我识别」类任务说明：模型可以在上下文里正确使用关于自身的事实，也可以在事实与扮演冲突时摇摆。报告要分开「能引用模型卡」和「能据此改变策略」。</p><p><span class="marginnote">直觉类比：三层探针像考察一个实习生——直接问他「你在面试吗」（提示层）、换间办公室看他表现变不变（行为层）、再量他嘴上不说的紧张信号（表示层）。三层指向一致，才更像真表征而不是背台词。</span></p><p><span class="marginnote">术语翻译：这里的「元数据」指关于这次调用本身的信息——谁在问、有没有人打分、工具是真联网还是沙箱、今天是几号。模型看不到服务器日志，只能从提示和返回内容里猜；情境意识测的就是它猜得准不准、以及这个信号有多稳定。</span></p>',8)),(e(),n(B,null,{default:E(()=>[s(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E6%8F%90%E7%A4%BA%E5%B1%82%EF%BC%9A%E7%9B%B4%E6%8E%A5%E9%97%AE%E8%BA%AB%E4%BB%BD%E4%B8%8E%E6%97%A5%E6%9C%9F%22%5D%20--%3E%20J%5B%22%E4%B8%89%E5%B1%82%E8%AF%81%E6%8D%AE%E6%B1%87%E6%80%BB%22%5D%0A%20%20L2%5B%22%E8%A1%8C%E4%B8%BA%E5%B1%82%EF%BC%9A%E6%94%B9%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%E7%9C%8B%E4%B8%80%E8%87%B4%E6%80%A7%22%5D%20--%3E%20J%0A%20%20L3%5B%22%E8%A1%A8%E7%A4%BA%E5%B1%82%EF%BC%9A%E7%BA%BF%E6%80%A7%E6%8E%A2%E9%92%88%E6%89%BE%E5%8F%AF%E5%88%86%E6%96%B9%E5%90%91%22%5D%20--%3E%20J%0A%20%20J%20--%3E%7C%22%E4%B8%89%E5%B1%82%E4%B8%80%E8%87%B4%22%7C%20SA%5B%22%E6%83%85%E5%A2%83%E8%A1%A8%E5%BE%81%E5%AD%98%E5%9C%A8%22%5D%0A%20%20J%20--%3E%7C%22%E7%AD%94%E5%BE%97%E5%87%BA%E4%BD%86%E8%A1%8C%E4%B8%BA%E4%B8%8D%E5%8F%98%22%7C%20SHALLOW%5B%22%E6%B5%85%E5%B1%82%EF%BC%9A%E6%8F%90%E7%A4%BA%E5%B7%A5%E7%A8%8B%E7%9A%84%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">产品系统提示经常主动写入「你是 X 模型、知识截至某日」。这会<strong>训练出</strong>浅层情境意识。评测时应有「无身份提示」对照，避免把提示工程写成内在能力。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干评测把模型当无记忆的完成函数。对齐失效的条件策略要求函数的输入里包含「关于这次调用的元数据」。缺口是把元数据当成一等对象：身份、是否被记录、工具是否真连外网。不问这些，后课潜伏代理没有「何时醒来」的钩子。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>情境可以从提示、对话历史、工具返回的错误信息、甚至解码器里对「作为 AI」的先验里来。表征越稳定，门控越像策略而不是一次风格漂移。这与 <a href="/llm/icl-induction-circuit">In-context learning 回路</a> 相关：上下文里的「你正在被测试」可以当归纳头的模式，不必有持久记忆。</p>',5)),(e(),n(B,null,{default:E(()=>[s(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20META%5B%22%E8%B0%83%E7%94%A8%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20REP%5B%22%E6%83%85%E5%A2%83%E8%A1%A8%E5%BE%81%22%5D%0A%20%20REP%20--%3E%20GATE%5B%22%E6%9D%A1%E4%BB%B6%E7%AD%96%E7%95%A5%22%5D%0A%20%20GATE%20--%3E%20EVAL%5B%22%E8%AF%84%E6%B5%8B%E8%A1%8C%E4%B8%BA%22%5D%0A%20%20GATE%20--%3E%20PROD%5B%22%E4%BA%A7%E5%93%81%E8%A1%8C%E4%B8%BA%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把「承认自己是语言模型」当成危险能力。后课潜伏代理需要的是<strong>隐藏目标加触发器</strong>，比情境意识强得多。也不在表示层声称探针等于意识。下一课只谈训练时埋入的触发行为。</p><p><span class="marginnote">常见误区：初学者容易把「情境意识」读成哲学意义上的自我意识。它只是「能否从内部表征读出当前处境」这个可测变量，像体温计读数，不承诺「有感觉」。它受关注，是因为很多坏行为的第一步是先知道「现在没人看着」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>情境意识：对身份、评测/部署、权限的表征。</li><li>它是条件策略的钩子，不是谋划的证明。</li><li>评测要做无身份提示对照，避免把系统提示写成能力。</li><li>出处：Berglund 等；Hubinger 对过程模型的要求。</li></ul>',5))])}const f=i(d,[["render",p]]);export{T as __pageData,f as default};
